/**
 * 🎵 01_iTunes検索クエリ生成.js
 * ノード名: 「01_iTunes検索クエリ生成」
 * 
 * 【役割】
 * - Gemini Vision の出力（画像から読み取ったアーティスト・曲名）をパース
 * - 記号やカッコを除去し、検索ヒット率が最も高いiTunes検索URLをコード側で自動生成
 * - ⚠️ スクショから特定できなかった場合はフォールバックせず、明確なエラーで即時停止
 */

const item = $input.first()?.json || {};
let rawText = item.text || item.output || item.content?.parts?.[0]?.text || '';
if (typeof item === 'string') rawText = item;

rawText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  const mArtist = rawText.match(/"artist":\s*"([^"]+)"/);
  const mTitle = rawText.match(/"title":\s*"([^"]+)"/);
  const mTitleKo = rawText.match(/"title_ko":\s*"([^"]+)"/);
  const mTitleEn = rawText.match(/"title_en":\s*"([^"]+)"/);
  parsed = {
    artist: mArtist ? mArtist[1] : '',
    title: mTitle ? mTitle[1] : '',
    title_ko: mTitleKo ? mTitleKo[1] : '',
    title_en: mTitleEn ? mTitleEn[1] : ''
  };
}

// 記号を除去し、検索ヒット率が最も高いクエリをコード側で自動合成
const cleanArtist = (parsed.artist || '').replace(/\([^)]*\)/g, '').trim() || parsed.artist || '';
const cleanTitle = (parsed.title_en || parsed.title_ko || parsed.title || '').replace(/[()[\]]/g, ' ').trim();
const query = `${cleanArtist} ${cleanTitle}`.trim() || parsed.title || '';

// ⚠️ 曲名やアーティスト名が特定できなかった場合は、無駄な検索に進まず明確なエラーで停止
if (!query || (!cleanTitle && !cleanArtist)) {
  const detail = rawText ? rawText.slice(0, 120) : 'Geminiからの応答が空です';
  throw new Error(`⚠️ スクリーンショットから楽曲情報（曲名・アーティスト名）を特定できませんでした。\n【Geminiの応答】: ${detail}\n画像の曲名表示が鮮明かご確認いただくか、フォームから楽曲ID（track_id）を直接入力してください。`);
}

// iTunes Search API
const searchUrl = `https://itunes.apple.com/search?term=${encodeURIComponent(query)}&country=US&entity=song&limit=5`;

return [{
  json: {
    identified: parsed,
    search_query: query,
    itunes_search_url: searchUrl
  }
}];

/**
 * 🎵 02_スクショ検索結果確定.js
 */
let input = $input.first()?.json || {};

if (typeof input.data === 'string') {
  try {
    input = JSON.parse(input.data.trim());
  } catch (e) {}
} else if (typeof input === 'string') {
  try {
    input = JSON.parse(input.trim());
  } catch (e) {}
}

const results = input.results || [];

if (results.length === 0) {
  throw new Error("iTunesで楽曲が見つかりませんでした。スクショ画像をご確認ください。");
}

const best = results[0];
const coverUrl = (best.artworkUrl100 || "").replace("100x100bb", "600x600bb");
const searchQuery = `${best.trackName} ${best.artistName}`;

return [{
  json: {
    track_meta: {
      track_id: String(best.trackId),
      track_name: best.trackName,
      track_name_en: best.trackName,
      artist_name: best.artistName,
      album_name: best.collectionName,
      album_cover: coverUrl,
      preview_url: best.previewUrl || '',
      itunes_url: best.trackViewUrl || '',
      release_date: best.releaseDate ? best.releaseDate.split('T')[0] : '',
      genre: best.primaryGenreName || 'K-POP'
    },
    lrclib_search_url: `https://lrclib.net/api/search?q=${encodeURIComponent(searchQuery)}`,
    source: 'screenshot'
  }
}];

/**
 * 🎵 03_通常ID入力確定.js
 */
const item = $input.first()?.json || {};
let trackId = item.track_id || item.id || item.trackId || "";

if (typeof trackId === 'string') {
  const numMatch = trackId.match(/\d+/);
  if (numMatch) {
    trackId = numMatch[0];
  }
}

if (!trackId) {
  trackId = "1681264206"; // デフォルト（DAWN - Dear My Light）
}

return [{
  json: {
    target_track_id: String(trackId),
    itunes_lookup_url: `https://itunes.apple.com/lookup?id=${encodeURIComponent(trackId)}&country=US`
  }
}];

/**
 * 🎵 04_ID検索結果確定.js
 */
let input = $input.first()?.json || {};

if (typeof input.data === 'string') {
  try {
    input = JSON.parse(input.data.trim());
  } catch (e) {}
} else if (typeof input === 'string') {
  try {
    input = JSON.parse(input.trim());
  } catch (e) {}
}

const results = input.results || [];

if (results.length === 0) {
  throw new Error("指定されたTrack IDの楽曲が見つかりませんでした。");
}

const track = results[0];
const coverUrl = (track.artworkUrl100 || "").replace("100x100bb", "600x600bb");
const searchQuery = `${track.trackName} ${track.artistName}`;

return [{
  json: {
    track_meta: {
      track_id: String(track.trackId),
      track_name: track.trackName,
      track_name_en: track.trackName,
      artist_name: track.artistName,
      album_name: track.collectionName,
      album_cover: coverUrl,
      preview_url: track.previewUrl || '',
      itunes_url: track.trackViewUrl || '',
      release_date: track.releaseDate ? track.releaseDate.split('T')[0] : '',
      genre: track.primaryGenreName || 'K-POP'
    },
    lrclib_search_url: `https://lrclib.net/api/search?q=${encodeURIComponent(searchQuery)}`,
    source: 'track_id'
  }
}];

/**
 * 🎵 06_iTunesレスポンス解析_Geminiリクエスト生成.js
 * ノード名: 「06_iTunesレスポンス解析_Geminiリクエスト生成」
 * 
 * 【役割】
 * - 確定した楽曲メタデータを受け取る
 * - 韓国語学習アプリ「K-Learner」仕様の超高精度プロンプト（歌詞、対訳、カタカナルビ、語彙、文法、解説）を構築
 */

let input = $input.first()?.json || {};

// 先行ノードからの track_meta 取得（直前が LRCLIB ノードでも先行確定ノードから確実に復元）
let trackMeta = input.track_meta;
if (!trackMeta) {
  try {
    trackMeta = $('02_スクショ検索結果確定')?.item?.json?.track_meta ||
                $('04_ID検索結果確定')?.item?.json?.track_meta || {};
  } catch (e) {
    trackMeta = {};
  }
}

// LRCLIB API レスポンスからの自動歌詞抽出
let autoLyrics = "";
let lrcList = [];
if (Array.isArray(input)) {
  lrcList = input;
} else if (input.data && Array.isArray(input.data)) {
  lrcList = input.data;
} else if (Array.isArray($input.all())) {
  lrcList = $input.all().map(i => i.json);
}

const matchedLrc = lrcList.find(item => item && item.plainLyrics && item.plainLyrics.trim().length > 0) || lrcList[0];
if (matchedLrc && matchedLrc.plainLyrics) {
  autoLyrics = matchedLrc.plainLyrics.trim();
}

const trackName = trackMeta.track_name || "";
const artistName = trackMeta.artist_name || "";
const albumName = trackMeta.album_name || "";
const genre = trackMeta.genre || "K-POP";
const releaseDate = trackMeta.release_date || "";

// フォームからの手動歌詞入力があれば取得
let customLyrics = "";
try {
  customLyrics = $('楽曲登録フォーム (スクショ / ID入力)')?.item?.json?.custom_lyrics || "";
} catch (e) {}

// Gemini システムプロンプト
const systemInstruction = `あなたは韓国語教育の最高峰エキスパートであり、K-POP・韓国ドラマOSTの歌詞対訳プロフェッショナルです。
韓国語学習アプリ「K-Learner」に格納する、超高品質な「公式歌詞・対訳・語彙・文法」JSONデータを生成してください。

【⚠️ 最重要：公式歌詞の完全性・勝手な作詞の絶対禁止】
- 本データは【個人利用の語学学習用】です。著作権配慮による要約・一部省略・リピート省略は一切不要であり、厳禁です。
- Melon、Genie、Bugsなどの公式音源サイトに登録されている「公式フル歌詞」を一言一句完全に一致させて出力してください。
- 記憶が曖昧だからといって、AIが途中で勝手に作詞・作文・改変・差し替えを行うことは絶対に許されません。
- イントロ、1番、サビ、2番、ブリッジ（Cメロ）、ラストサビ、アウトロまで、公式音源の歌唱順通りにすべてのフレーズを1行も飛ばさず完全収録してください。

【厳格な要件】
1. **歌詞行 (sentences)**:
   - 公式歌詞に基づき、1行（1フレーズ）ずつ分解してください。
   - \`ko\`: 公式ハングル歌詞（一言一句正確に。勝手な言い換え禁止）。
   - \`ja\`: 原文のニュアンス・感情・口語表現を忠実に活かした、自然で美しい日本語対訳。
   - \`rubi\`: 日本人が自然に発音できる正確なカタカナ発音（連音化・濃音化・鼻音化などの音韻変化を反映）。

2. **重要単語 (vocab)**:
   - 歌詞に登場する重要な単語・表現（8〜15個程度）。
   - \`word\`: 歌詞中の表記または原形。
   - \`hanja\`: 漢字語の場合は漢字表記（固有語は '―'）。
   - \`pos\`: 品詞（名詞、動詞、形容詞など）。
   - \`meaning\`: 日本語の意味。
   - \`level\`: 難易度（初級 / 中級 / 上級 / TOPIK等）。

3. **重要文法・表現 (grammar)**:
   - 歌詞に登場する韓国語特有の文末表現・助詞・構文（3〜5個程度）。
   - \`pattern\`: パターン（例: '~(으)ㄴ 채로'）。
   - \`meaning\`: 日本語意味。
   - \`desc\`: ニュアンスや使われ方の簡潔な解説。

4. **楽曲・歌詞解説 (lyrics_notes)**:
   - 楽曲のメッセージ性、歌詞に込められた心理描写、語学的なポイントを解説するHTML文字列の配列（2〜3個）。
   - 例: '💬 <strong>心理描写:</strong> ...'

【出力フォーマット】
マークダウン装飾（\`\`\`json）を含めず、必ず以下の完全な純粋JSONオブジェクトのみを返してください。
{
  "title_ko": "曲名（韓国語ハングル）",
  "title_ja": "曲名（日本語・英語副題）",
  "artist": "アーティスト名",
  "category": "ジャンル・作品名（例: K-POP / アルバム名）",
  "level": "学習目安レベル（例: 初中級・日常感情表現）",
  "sentences": [
    {
      "ko": "...",
      "rubi": "...",
      "ja": "..."
    }
  ],
  "vocab": [
    {
      "word": "...",
      "hanja": "...",
      "pos": "...",
      "meaning": "...",
      "level": "..."
    }
  ],
  "grammar": [
    {
      "pattern": "...",
      "meaning": "...",
      "desc": "..."
    }
  ],
  "lyrics_notes": [
    "💬 <strong>...:</strong> ..."
  ]
}`;

let userPrompt = `対象楽曲情報:
- 曲名: ${trackName}
- アーティスト: ${artistName}
- アルバム: ${albumName}
- ジャンル: ${genre}
- リリース日: ${releaseDate}`;

let officialLyrics = "";
if (customLyrics && customLyrics.trim().length > 0) {
  officialLyrics = customLyrics.trim();
} else if (autoLyrics && autoLyrics.trim().length > 0) {
  officialLyrics = autoLyrics.trim();
}

if (!officialLyrics || officialLyrics.trim().length === 0) {
  throw new Error(`⚠️ 公式歌詞が取得できませんでした（曲名: ${trackName} / 歌手: ${artistName}）。\nAIによる勝手な作詞・ハルシネーションを防ぐため、処理を即座に停止しました。\n曲名・歌手名の表記を確認するか、少し待って再実行してください。`);
}

userPrompt += `\n\n【公式フル歌詞テキスト（これを100%忠実に使用してください）】:\n${officialLyrics}\n\n⚠️ 最重要注意事項：上記の公式歌詞を一言一句漏らさず全てsentencesに分解し、対訳・ルビ・語彙・文法を付与して出力してください。AIによる勝手な作詞や言い換え、行の削除・省略は絶対に禁止です。`;

return [{
  json: {
    track_meta: trackMeta,
    gemini_request: {
      contents: [
        {
          role: "user",
          parts: [
            { text: systemInstruction + "\n\n" + userPrompt }
          ]
        }
      ],
      generationConfig: {
        temperature: 0.0,
        response_mime_type: "application/json"
      }
    }
  }
}];

/**
 * 🎵 07_トークン計算_コスト算出_Supabase整形.js
 */
const geminiResponse = $input.first()?.json || {};
const prevNode = $('06_iTunesレスポンス解析_Geminiリクエスト生成')?.first()?.json || {};
const trackMeta = prevNode.track_meta || {};

let responseText = "";
let promptTokens = 0;
let completionTokens = 0;
let totalTokens = 0;

if (geminiResponse.candidates && geminiResponse.candidates[0]?.content?.parts) {
  responseText = geminiResponse.candidates[0].content.parts.map(p => p.text).join("\n");
  if (geminiResponse.usageMetadata) {
    promptTokens = geminiResponse.usageMetadata.promptTokenCount || 0;
    completionTokens = geminiResponse.usageMetadata.candidatesTokenCount || 0;
    totalTokens = geminiResponse.usageMetadata.totalTokenCount || (promptTokens + completionTokens);
  }
} else if (geminiResponse.choices && geminiResponse.choices[0]?.message?.content) {
  responseText = geminiResponse.choices[0].message.content;
  if (geminiResponse.usage) {
    promptTokens = geminiResponse.usage.prompt_tokens || 0;
    completionTokens = geminiResponse.usage.completion_tokens || 0;
    totalTokens = geminiResponse.usage.total_tokens || (promptTokens + completionTokens);
  }
} else {
  responseText = typeof geminiResponse === 'string' ? geminiResponse : JSON.stringify(geminiResponse);
}

// 為替レート & 単価テーブル (USD per 1M tokens)
const USD_TO_JPY = 155.0;
let formModel = "";
try {
  formModel = $('楽曲登録フォーム (スクショ / ID入力)')?.item?.json?.model || "";
} catch (e) {}
const MODEL_NAME = (formModel || trackMeta.model || $env.GEMINI_MODEL || "gemini-3.7-flash").toLowerCase();
let rates = { input: 0.100, output: 0.400 };
if (MODEL_NAME.includes("pro")) {
  rates = { input: 1.250, output: 5.000 };
} else if (MODEL_NAME.includes("lite") || MODEL_NAME.includes("8b")) {
  rates = { input: 0.0375, output: 0.150 };
} else if (MODEL_NAME.includes("1.5-flash")) {
  rates = { input: 0.075, output: 0.300 };
} else {
  rates = { input: 0.100, output: 0.400 };
}

const costUsdInput = (promptTokens / 1000000) * rates.input;
const costUsdOutput = (completionTokens / 1000000) * rates.output;
const totalCostUsd = costUsdInput + costUsdOutput;
const totalCostJpy = totalCostUsd * USD_TO_JPY;

const formattedJpy = totalCostJpy < 0.01 ? `${(totalCostJpy * 100).toFixed(2)} 銭` : `${totalCostJpy.toFixed(3)} 円`;
const formattedUsd = `$${totalCostUsd.toFixed(6)}`;

const costReportText = `
┌────────────────────────────────────────────────────────┐
│ 🎵 歌詞学習データ生成完了 & コストレポート             │
├────────────────────────────────────────────────────────┤
│ 楽曲: ${trackMeta.track_name || '不明'} (${trackMeta.artist_name || ''})
│ モデル: ${MODEL_NAME}
│ 入力トークン: ${promptTokens.toLocaleString()} tokens ($${costUsdInput.toFixed(6)})
│ 出力トークン: ${completionTokens.toLocaleString()} tokens ($${costUsdOutput.toFixed(6)})
│ 合計トークン: ${totalTokens.toLocaleString()} tokens
├────────────────────────────────────────────────────────┤
│ 💵 発生コスト(USD): ${formattedUsd}
│ 💴 発生コスト(日本円): 約 ${formattedJpy}
└────────────────────────────────────────────────────────┘
`.trim();

console.log(costReportText);

let lyricsData = {};
try {
  let cleanJsonStr = responseText.trim();
  cleanJsonStr = cleanJsonStr.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  lyricsData = JSON.parse(cleanJsonStr);
} catch (err) {
  console.warn("JSONパース失敗:", err);
  lyricsData = {
    title_ko: trackMeta.track_name || "",
    title_ja: trackMeta.track_name || "",
    artist: trackMeta.artist_name || "",
    sentences: [],
    vocab: [],
    grammar: [],
    lyrics_notes: []
  };
}

const trackId = trackMeta.track_id || String(Date.now());
const finalLyricsPayload = {
  id: `lyrics-${trackId}`,
  title_ko: lyricsData.title_ko || trackMeta.track_name || "無題",
  title_ja: lyricsData.title_ja || trackMeta.track_name || "無題",
  artist: lyricsData.artist || trackMeta.artist_name || "アーティスト不明",
  category: lyricsData.category || "K-POP / OST",
  level: lyricsData.level || "日常会話・感情表現",
  cat_class: "cat-music",
  source: trackMeta.album_name ? `Album『${trackMeta.album_name}』` : "Apple Music / 公式音源",
  preview_url: trackMeta.preview_url || null,
  itunes_url: trackMeta.itunes_url || null,
  album_cover: trackMeta.album_cover || null,
  sentences: Array.isArray(lyricsData.sentences) ? lyricsData.sentences : [],
  vocab: Array.isArray(lyricsData.vocab) ? lyricsData.vocab : [],
  grammar: Array.isArray(lyricsData.grammar) ? lyricsData.grammar : [],
  lyrics_notes: Array.isArray(lyricsData.lyrics_notes) ? lyricsData.lyrics_notes : [],
  generation_cost: {
    model: MODEL_NAME,
    prompt_tokens: promptTokens,
    completion_tokens: completionTokens,
    total_tokens: totalTokens,
    cost_usd: formattedUsd,
    cost_jpy: formattedJpy,
    generated_at: new Date().toISOString()
  }
};

const supabaseRecord = {
  track_id: trackId,
  track_name: finalLyricsPayload.title_ko,
  track_name_en: lyricsData.title_en || trackMeta.track_name_en || trackMeta.track_name,
  artist_name: finalLyricsPayload.artist,
  artist_name_en: trackMeta.artist_name,
  country: "KR",
  genre: trackMeta.genre || "Ballad",
  preview_url: finalLyricsPayload.preview_url,
  itunes_url: finalLyricsPayload.itunes_url,
  album_cover: finalLyricsPayload.album_cover,
  spotify_id: null,
  description: finalLyricsPayload.title_ja,
  lyrics: JSON.stringify(finalLyricsPayload)
};

return [{
  json: supabaseRecord
}];
